edits.after:
// Handle Escape key for non-modal dialogs (native cancel doesn't fire for show())
// and for modal dialogs with keyboard: false to prevent the native cancel event.
EventHandler.on(this._element, `keydown${EVENT_KEY}`, event => {
  if (event.key !== 'Escape') {
    return
  }

  if (this._openedAsModal) {
    if (!this._config.keyboard) {
      event.preventDefault()
      event.stopImmediatePropagation()
    }
    return
  }

  event.preventDefault()

  if (!this._config.keyboard) {
    return
  }

  this._onCancel()
  this.hide()
})
